sp_widget.client_script:
api.controller = function($location) {

    var c = this;


    c.form = {

        name: "",

        username: "",

        email: "",

        password: "",

        confirmPassword: ""

    };


    c.submitting = false;

    c.errorMessage = "";

    c.successMessage = "";


    // ==========================================
    // REGISTER
    // ==========================================

    c.register = function() {

        c.errorMessage = "";

        c.successMessage = "";


        if (!c.form.name ||
            !c.form.username ||
            !c.form.email ||
            !c.form.password ||
            !c.form.confirmPassword) {

            c.errorMessage =
                "Please fill in all fields.";

            return;
        }


        if (c.form.password !==
            c.form.confirmPassword) {

            c.errorMessage =
                "Passwords do not match.";

            return;
        }


        if (c.form.password.length < 6) {

            c.errorMessage =
                "Password must contain at least 6 characters.";

            return;
        }


        var emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        if (!emailRegex.test(c.form.email)) {
            c.errorMessage = "Please enter a valid email address (e.g., name@gmail.com).";
            return;
        }

        c.submitting = true;


        c.server.get({

            action: "register",

            name: c.form.name,

            username: c.form.username,

            email: c.form.email,

            password: c.form.password

        }).then(function(response) {

            c.submitting = false;


            if (response.data.success === true) {

                c.successMessage =
                    "Account created successfully. Redirecting to login...";


                setTimeout(function() {

                    $location.search({
                        id: "claim_login"
                    });

                }, 2000);


            } else {

                c.errorMessage =
                    response.data.message ||
                    "Unable to create account.";

            }

        }, function() {

            c.submitting = false;

            c.errorMessage =
                "Unable to create account.";

        });

    };


    // ==========================================
    // GO TO LOGIN
    // ==========================================

    c.goToLogin = function() {

        $location.search({
            id: "claim_login"
        });

    };

};

sp_widget.css:
.ich-signup-page {

    min-height: 100vh;

    display: flex;

    align-items: center;

    justify-content: center;

    padding: 35px 20px;

    background:
        linear-gradient(
            135deg,
            #eef6ff,
            #f8fbff,
            #edf4ff
        );

    box-sizing: border-box;

}


.ich-signup-card {

    width: 100%;

    max-width: 460px;

    background: #ffffff;

    padding: 35px 40px 28px;

    border-radius: 20px;

    box-shadow:
        0 20px 60px rgba(30, 64, 175, 0.14);

    border: 1px solid #e5ebf3;

}


.signup-brand {

    text-align: center;

    margin-bottom: 25px;

}


.signup-logo {

    width: 60px;

    height: 60px;

    margin: auto;

    border-radius: 16px;

    display: flex;

    align-items: center;

    justify-content: center;

    font-size: 28px;

    background:
        linear-gradient(
            135deg,
            #1261d6,
            #2383e2
        );

}


.signup-brand h1 {

    margin: 12px 0 4px;

    color: #12305b;

    font-size: 23px;

}


.signup-brand p {

    margin: 0;

    color: #7c8da2;

    font-size: 12px;

}


.signup-title {

    text-align: center;

    margin-bottom: 22px;

}


.signup-title h2 {

    margin: 0;

    color: #16345f;

    font-size: 21px;

}


.signup-title p {

    margin: 7px 0 0;

    color: #7a8ba3;

    font-size: 12px;

}


.signup-field {

    margin-bottom: 16px;

}


.signup-field label {

    display: block;

    margin-bottom: 7px;

    color: #344967;

    font-size: 12px;

    font-weight: 600;

}


.signup-field input {

    width: 100%;

    height: 45px;

    padding: 0 13px;

    border: 1px solid #d6e0ed;

    border-radius: 8px;

    background: #f8fbff;

    color: #243b5a;

    outline: none;

    box-sizing: border-box;

}


.signup-field input:focus {

    background: #ffffff;

    border-color: #2674dc;

    box-shadow:
        0 0 0 3px rgba(37, 99, 235, 0.10);

}


.signup-error {

    margin: 12px 0;

    padding: 10px;

    border-radius: 7px;

    background: #fff1f2;

    color: #be123c;

    font-size: 12px;

}


.signup-success {

    margin: 12px 0;

    padding: 10px;

    border-radius: 7px;

    background: #ecfdf5;

    color: #047857;

    font-size: 12px;

}


.signup-submit {

    width: 100%;

    height: 47px;

    margin-top: 5px;

    border: none;

    border-radius: 8px;

    background:
        linear-gradient(
            135deg,
            #1466d4,
            #247fe0
        );

    color: white;

    font-size: 13px;

    font-weight: 700;

    cursor: pointer;

}


.signup-submit:hover {

    opacity: 0.94;

}


.signup-submit:disabled {

    opacity: 0.6;

    cursor: not-allowed;

}


.back-login {

    text-align: center;

    margin-top: 22px;

    padding-top: 18px;

    border-top: 1px solid #edf1f5;

    color: #7a8ba3;

    font-size: 12px;

}


.back-login button {

    border: none;

    background: transparent;

    color: #1769d1;

    font-weight: 700;

    cursor: pointer;

}


.signup-security {

    text-align: center;

    margin-top: 18px;

    color: #9aa7b6;

    font-size: 10px;

}


@media (max-width: 500px) {

    .ich-signup-card {

        padding: 28px 22px;

    }

}

sp_widget.script:
(function() {

    data.success = false;
    data.message = "";


    if (!input ||
        input.action != "register") {

        return;
    }


    var name =
        String(input.name || "").trim();

    var username =
        String(input.username || "").trim();

    var email =
        String(input.email || "").trim();

    var password =
        String(input.password || "");


    // ==========================================
    // VALIDATION
    // ==========================================

    if (!name ||
        !username ||
        !email ||
        !password) {

        data.message =
            "Please fill in all required fields.";

        return;
    }


    // ==========================================
    // CHECK USERNAME
    // ==========================================

    var existingUser =
        new GlideRecord("sys_user");

    existingUser.addQuery(
        "user_name",
        username
    );

    existingUser.setLimit(1);

    existingUser.query();


    if (existingUser.next()) {

        data.message =
            "Username already exists.";

        return;
    }


    // ==========================================
    // CHECK EMAIL
    // ==========================================

    var existingEmail =
        new GlideRecord("sys_user");

    existingEmail.addQuery(
        "email",
        email
    );

    existingEmail.setLimit(1);

    existingEmail.query();


    if (existingEmail.next()) {

        data.message =
            "Email address is already registered.";

        return;
    }


    // ==========================================
    // CREATE USER
    // ==========================================

    var user =
        new GlideRecord("sys_user");

    user.initialize();


    user.setValue(
        "name",
        name
    );


    user.setValue(
        "user_name",
        username
    );


    user.setValue(
        "email",
        email
    );


    /*
     * Password
     */

    user.setValue(
        "user_password",
        password
    );


    /*
     * Active user
     */

    user.setValue(
        "active",
        true
    );


    var userSysId =
        user.insert();


    if (!userSysId) {

        data.message =
            "Unable to create user account.";

        return;
    }


    data.success = true;

    data.message =
        "Account created successfully.";

})();
